DROP TABLE [wcs_task]
GO
CREATE TABLE [wcs_task] (
[id] bigint NOT NULL IDENTITY(1,1) ,
[task_no] varchar(50) NULL DEFAULT '' ,
[task_type] varchar(50) NULL DEFAULT '' ,
[status] varchar(20) NULL DEFAULT '' ,
[barcode] varchar(400) NULL DEFAULT '' ,
[length] varchar(30) NULL ,
[width] varchar(30) NULL ,
[height] varchar(30) NULL ,
[volume] varchar(30) NULL ,
[weight] varchar(30) NULL ,
[cur_pos] varchar(30) NULL DEFAULT '' ,
[to_pos] varchar(30) NULL DEFAULT '' ,
[create_date] datetime NULL DEFAULT (getdate()) ,
[update_date] datetime NULL ,
[priority] varchar(30) NULL DEFAULT '' ,
[temp1] varchar(255) NULL DEFAULT '' ,
[temp2] varchar(255) NULL DEFAULT '' ,
[temp3] varchar(255) NULL DEFAULT '' ,
[temp4] varchar(255) NULL DEFAULT '' ,
[temp5] varchar(255) NULL DEFAULT '' ,
[receiver_name] varchar(255) NULL ,
[shipment_id] varchar(50) NULL ,
[url] varchar(600) NULL ,
[parcelId] int NULL ,
[plc_to_pos] varchar(20) NULL ,
[sort_code] varchar(200) NULL 
)


