CREATE PROCEDURE [sp_create_wcs_log]                             
@WORK_NAME   VARCHAR(100),               /*1、作业名称 */
@barcode     VARCHAR(100),               /*2、容器号 */
@to_pos      VARCHAR(100),               /*3、应去口 */
@CUR_POS     VARCHAR(100),               /*4、实际口 */
@BCR_NO      VARCHAR(100),               /*5、读码器 */
@sort_status     VARCHAR(100),           /*6、分拣状态 */
@WORK_CODE   VARCHAR(100),               /*7、执行代码 */
@WORK_MSG    VARCHAR(4000),              /*8、执行信息 */
@WORK_PROC   VARCHAR(100),               /*9、执行过程 */
@WORK_SEC    int,                        /*10、执行时间 */
@dvc_no      VARCHAR(100),               /*11、dvc编号 */
@TEMP1       VARCHAR(2000),               /*12、备用1 */
@TEMP2       VARCHAR(2000),               /*13、备用2 */
@TEMP3       VARCHAR(2000),               /*14、备用3 */
@status       VARCHAR(2000),               /*15、备用4 */
@Induction_status       VARCHAR(2000),                /*16、备用5 */
@wcsTaskNum  VARCHAR(2000)                 /*17、任务号 */

                            
as
  begin
      INSERT INTO wcs_log( work_name,barcode,to_pos,cur_pos,bcr_no,sort_status,work_code,work_msg,work_proc,work_sec,dvc_no,temp1,temp2,temp3,status,Induction_status,wcsTaskNum) 
			VALUES (@work_name,@barcode,@to_pos,@cur_pos,@bcr_no,@sort_status,@work_code,@work_msg,@work_proc,@work_sec,@dvc_no,@temp1,@temp2,@temp3,@status,@Induction_status,@wcsTaskNum)
	
	END

