-- ----------------------------
-- Procedure structure for sp_get_sort_sum_report
-- ----------------------------
DROP PROCEDURE [sp_get_sort_sum_report]
GO
CREATE PROCEDURE [sp_get_sort_sum_report]
    @begin_date DATETIME,
    @end_date DATETIME,
    @dvc_no VARCHAR(100) = NULL,  
    @stat_type VARCHAR(10) = 'Hour', /* 'Day' 或 'Hour' */
    @his varchar(10) = '0'
AS
BEGIN
    SET NOCOUNT ON;

    /* =========================================================
       1. 预处理：动态确定日期格式化截取长度
       ========================================================= */
    /* 如果按天统计截取前10位(yyyy-MM-dd)，按小时则截取前13位(yyyy-MM-dd HH) */
    DECLARE @fmt_len INT = CASE WHEN LOWER(@stat_type) = 'day' THEN 10 ELSE 13 END;

    /* =========================================================
       2. 创建临时表 (具备精确统计信息，支撑百万级数据高效聚合)
       ========================================================= */
    IF OBJECT_ID('tempdb..#TempLog') IS NOT NULL DROP TABLE #TempLog;
    IF OBJECT_ID('tempdb..#TempTask') IS NOT NULL DROP TABLE #TempTask;

    CREATE TABLE #TempLog (
        [DATE] VARCHAR(13) COLLATE DATABASE_DEFAULT,
        status VARCHAR(100) COLLATE DATABASE_DEFAULT,
        cur_pos VARCHAR(100) COLLATE DATABASE_DEFAULT 
    );
    CREATE TABLE #TempTask (
        [DATE] VARCHAR(13) COLLATE DATABASE_DEFAULT,
        barcode VARCHAR(4000) COLLATE DATABASE_DEFAULT
    );

    /* =========================================================
       3. 数据抽取 (利用 @fmt_len 精简提取逻辑，统一转换为13位)
       ========================================================= */
    IF @his = '1'
    BEGIN
        INSERT INTO #TempLog
        SELECT CONVERT(VARCHAR(13), create_date, 120), status, cur_pos
        FROM [dbo].[wcs_log_bak] WITH (NOLOCK)
        WHERE work_name = 'sd_report_confirm' 
          AND create_date >= @begin_date AND create_date <= @end_date
          AND (@dvc_no IS NULL OR @dvc_no = '' OR dvc_no = @dvc_no)
        OPTION (RECOMPILE);
        
        INSERT INTO #TempTask
        SELECT CONVERT(VARCHAR(13), create_date, 120), barcode
        FROM [dbo].[wcs_task_bak] WITH (NOLOCK)
        WHERE task_type = 'cv' AND (cur_pos IS NULL OR cur_pos = '') 
          and barcode <> 'NoRead'
          AND create_date >= @begin_date AND create_date <= @end_date
          AND create_date <= DATEADD(MINUTE, -5, GETDATE())
        OPTION (RECOMPILE);
    END
    ELSE
    BEGIN
        INSERT INTO #TempLog
        SELECT CONVERT(VARCHAR(13), create_date, 120), status, cur_pos
        FROM [dbo].[wcs_log] WITH (NOLOCK)
        WHERE work_name = 'sd_report_confirm' 
          AND create_date >= @begin_date AND create_date <= @end_date
          AND (@dvc_no IS NULL OR @dvc_no = '' OR dvc_no = @dvc_no)
        OPTION (RECOMPILE);
        
        INSERT INTO #TempTask
        SELECT CONVERT(VARCHAR(13), create_date, 120), barcode
        FROM [dbo].[wcs_task] WITH (NOLOCK)
        WHERE task_type = 'cv' AND (cur_pos IS NULL OR cur_pos = '') 
          and barcode <> 'NoRead'
          AND create_date >= @begin_date AND create_date <= @end_date
          AND create_date <= DATEADD(MINUTE, -5, GETDATE())
        OPTION (RECOMPILE);
    END

    /* =========================================================
       4. 聚合计算与最终结果合并输出
       ========================================================= */
    ;WITH LogStats AS (
        SELECT 
            /* 在最外层聚合时，利用 LEFT 函数一把完成时间精度的截断 */
            LEFT([DATE], @fmt_len) AS [DATE],
            COUNT(1) AS Total,
            COUNT(1) - SUM(CASE WHEN cur_pos IN ('71', '72') THEN 1 ELSE 0 END) AS Normal,
            SUM(CASE WHEN cur_pos IN ('71', '72') THEN 1 ELSE 0 END) AS Reject,
            SUM(CASE WHEN status = '101' THEN 1 ELSE 0 END) AS NoRead,
            SUM(CASE WHEN status = '102' THEN 1 ELSE 0 END) AS NoTask,
            SUM(CASE WHEN status = '103' THEN 1 ELSE 0 END) AS ApiTimeOut,
            SUM(CASE WHEN status = '104' THEN 1 ELSE 0 END) AS DropFail,
            SUM(CASE WHEN status = '6' THEN 1 ELSE 0 END) AS ChuteLock,
            SUM(CASE WHEN status = '5' THEN 1 ELSE 0 END) AS ChuteFull,
            SUM(CASE WHEN status = '105' THEN 1 ELSE 0 END) AS MultipleBarcodes,
            SUM(CASE WHEN status = '7' THEN 1 ELSE 0 END) AS GapTooSmall,
            SUM(CASE WHEN status = '10' THEN 1 ELSE 0 END) AS ParcelTooLarge,
            SUM(CASE WHEN status = '8' THEN 1 ELSE 0 END) AS ParcelLost
        FROM #TempLog
        GROUP BY LEFT([DATE], @fmt_len)
    ),
    TaskStats AS (
        SELECT 
            LEFT([DATE], @fmt_len) AS [DATE],
            COUNT(DISTINCT barcode) AS CvEmptyPosCount
        FROM #TempTask
        GROUP BY LEFT([DATE], @fmt_len)
    )
    SELECT 
        ISNULL(L.[DATE] COLLATE DATABASE_DEFAULT, T.[DATE] COLLATE DATABASE_DEFAULT) AS [DATE],
        ISNULL(L.Total, 0) AS Total,
        ISNULL(L.Normal, 0) AS Normal,
        ISNULL(L.Reject, 0) AS Reject,
        ISNULL(L.NoRead, 0) AS NoRead,
        ISNULL(L.NoTask, 0) AS NoTask,
        ISNULL(L.ApiTimeOut, 0) AS ApiTimeOut,
        ISNULL(L.DropFail, 0) AS DropFail,
        ISNULL(L.ChuteLock, 0) AS ChuteLock,
        ISNULL(L.ChuteFull, 0) AS ChuteFull,
        ISNULL(L.MultipleBarcodes, 0) AS MultipleBarcodes,
        ISNULL(L.GapTooSmall, 0) AS GapTooSmall,
        ISNULL(L.ParcelTooLarge, 0) AS ParcelTooLarge,
        ISNULL(L.ParcelLost, 0) AS ParcelLost,
        ISNULL(T.CvEmptyPosCount, 0) AS PlcTimeOut
    FROM LogStats L
    FULL OUTER JOIN TaskStats T 
        ON L.[DATE] COLLATE DATABASE_DEFAULT = T.[DATE] COLLATE DATABASE_DEFAULT
    ORDER BY 
        [DATE] DESC;

    /* =========================================================
       5. 清理临时表
       ========================================================= */
    IF OBJECT_ID('tempdb..#TempLog') IS NOT NULL DROP TABLE #TempLog;
    IF OBJECT_ID('tempdb..#TempTask') IS NOT NULL DROP TABLE #TempTask;

END
GO

