-- Procedure structure for sp_hc3_wms_applyContainer_send
-- ----------------------------
DROP PROCEDURE [sp_hc3_wms_applyContainer_send]
GO

CREATE PROCEDURE [sp_hc3_wms_applyContainer_send] /*多件集货完成 */
  @P_uuid VARCHAR(4000) OUT,
	@p_Send VARCHAR(4000) OUT,
  @P_CODE VARCHAR(100) OUT,
  @P_MSG VARCHAR(4000) OUT
AS
 /*向wms发送   设备状态回传接口*/
	DECLARE @header VARCHAR(4000) = '';/*设置的头*/
	DECLARE @body VARCHAR(4000) = '';/*发送的body*/
	DECLARE @id varchar(100)
	DECLARE @uuid varchar(100)
	DECLARE @s_body VARCHAR(4000);
	declare    
	      @wcsTaskNum varchar(100)='',                  
        @containerNum varchar(4000)='',                 
        @containerType varchar(20)='',                
        @pointCode varchar(100)='';                  

  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN 
  set @p_uuid=''
  set @p_send=''
  
  select top 1 @pointCode= wcs_to_pos from wcs_pos_config where wcs_to_pos in ('230','233') and stn_st='1' order by create_date asc  
  update wcs_pos_config set create_date=getdate() where wcs_to_pos = @pointCode
	if isnull(@pointCode,'')<>''
  begin    
    select top 1 @id=id from wcs_task where task_type='applyContainer' and cur_pos = isnull(@pointCode,'') and status='0'
    if isnull(@id,'')=''
    begin
      SET @uuid = replace(newid(),'-','')
      set @containerType = case @pointCode when '230' then '30' else '40' end
      set @wcsTaskNum = @uuid
      set @containerNum ='1'
      SET @s_body= '{"reqCode":"'+@uuid+'","data":[{"pointCode":"'+isnull(@pointCode,'')
		    +'","containerNum":"'+isnull(@containerNum,'')+'","containerType":"'
			  +isnull(@containerType,'')+'","wcsTaskNum":"'+isnull(@wcsTaskNum,'')+'"}]}'  
		  set @p_Send = 'Content-Type@@application/json#####'+@s_body  
    end
  end    	  		 																			 																						  		 	   
END



GO

