CREATE PROCEDURE [sp_hc46_shopee_scan_rev-bak1]
  @p_uuid varchar(100), 
	@p_Send VARCHAR(4000),
  @p_Rev VARCHAR(4000),
  @P_CODE VARCHAR(4000) OUT,
  @P_MSG VARCHAR(4000) OUT
AS
	DECLARE @LOG varchar(1000)
	  ,@BCR_NO VARCHAR(50) = '',@dvc_no VARCHAR(50) = '';
	DECLARE @v_DATE1 DATETIME = GETDATE(),@v_s INT = 0;
	DECLARE @Destination01 VARCHAR(10)
	  ,@id bigint,@barcode varchar(200),@ParcelID int,@TrackID int,@Induction int
	  ,@msg2 varchar(500),@sCode varchar(50),@to_pos varchar(50)
		,@tel_sn varchar(20),@url varchar(1000)
  declare @retcode varchar(20),@message varchar(200),@msg1 varchar(200),@disp_info varchar(400),
    @sorting_direction varchar(100),@scan_id varchar(100),@scan_number varchar(100),@status varchar(20)
	BEGIN
	  /*set @p_Rev='{"code":"0","message":"ok","data":[{"pointCode":"111"},{"pointCode":"112"}],"reqCode":"1DC0AA91-26F7-4E2F-8572-350A6AF624E6"}' */
		/*set @p_Rev='' */
	  set	 @P_MSG = ''
		set	 @P_CODE = ''
	  BEGIN TRY	
		  			   /*根据条码取出任务表的信息，组装目的地回复报文 */     
      SELECT @id=id,@barcode=barcode,@ParcelID=ParcelID,@TrackID=TrackID,@Induction=Induction,@BCR_NO=bcr,@dvc_no=dvc_no,@tel_sn=tel_sn,@url=url			  
			FROM wcs_tools_parcel where msg=@p_send and type='cv'
			/*delete from wcs_tools_parcel where id = @id 	  */
								 								  
			BEGIN TRY		
			  SELECT @retcode=retcode,@message=message FROM (SELECT a.parent_ID, a.NAME, a.StringValue
          FROM   f_tools_parseJSON(@p_rev) a where isnull(a.name,'')in('retcode','message') )t1
            PIVOT (MAX(StringValue) FOR NAME IN(retcode,message)) AS t2		    
               
        SELECT @scan_id=shipment_id, @sorting_direction=sort_code 
          FROM (SELECT a.parent_ID, a.NAME, a.StringValue FROM f_tools_parseJSON(@p_rev) a 
			    where isnull(a.name,'') in ('shipment_id','sort_code')) t1
            PIVOT (MAX(StringValue) FOR NAME IN (shipment_id,sort_code)) AS t2	                         
	    end try
     	BEGIN CATCH
        set @msg2='json异常'
				set @status='103'	 
      END CATCH	
			
			set @msg1= dbo.f_tools_mem('wms_std_'+isnull(@retcode,''))
			if @retcode in ('0')	
			begin				
				delete from wcs_task where barcode= @barcode and task_type='cv' 
							 							 											 																																																																		      
        INSERT INTO wcs_task( barcode,to_pos,task_type,sorting_direction,scan_id,scan_number,url,status)  
          SELECT @barcode, a.StringValue, 'cv', @sorting_direction, isnull(@scan_id,''), @scan_number, @url, @status
          FROM f_tools_parseJSON(@p_rev) a 
			      where a.name = 'chute_id' and isnull(a.StringValue,'') <> ''   																																																																																																										 																																																																		      															      
				
				SELECT @to_pos=STUFF(
          (
            SELECT ',' + CAST(to_pos AS VARCHAR(50))
            FROM wcs_task 
            WHERE barcode = @barcode AND task_type = 'cv'
            FOR XML PATH('')
          ), 1, 1, '') 	
					
				if isnull(@to_pos,'')='' 
				begin
				  set @to_pos = dbo.f_tools_mem('bcr_no_'+'1001')	
				  set @msg2=isnull(@msg2,'')+',no chute,'
				end 							  
			end	
			else
			begin
				set @status='102'										
				set @to_pos=	dbo.f_tools_mem('bcr_no_'+'1001')	 					 																 
				INSERT INTO wcs_task( barcode,to_pos,task_type,sorting_direction,scan_id,scan_number,url,status) 
				  values(@barcode,@to_pos,'cv','','','',@url,@status) 			
			end	
					  											
			exec sp_sd_make_msg	'08',@dvc_no,@barcode,@to_pos,'0',@BCR_NO,@ParcelID,@TrackID,@Induction,@P_msg out  								
			SET @LOG = '[sd_request_46]'+isnull(@msg2,'')+ ISNULL(@Barcode,'') +',message='+isnull(@message,'')
			  +',msg1='+ isnull(@msg1,'') +',scan_id='+isnull(@scan_id,'')+',to_pos:' +isnull(@to_pos,'')
				+',Bcr' +isnull(@BCR_NO,'')+',id:' 
				+ isnull(CAST(@ParcelID AS VARCHAR),'') +',retcode='+	isnull(@retcode,'')														 	  																																				 		 												 																																																 																		 																																						 							 														 			 	 		 															       			                     
    end try
    BEGIN CATCH
      SELECT @scode = ERROR_NUMBER(), @LOG  = ERROR_MESSAGE()
    END CATCH

    set @p_code=@LOG
    /*set @P_MSG='plc1&=363637' */
    SET @v_s    = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100
    set @p_msg = isnull(@p_msg,'')    
    EXEC [dbo].[sp_create_wcs_log]
	  	'sd_request_46',            /*1、作业名称 */
	  	@barcode,                   /*2、容器号 */
	  	@to_pos,                   /*3、应去口 */
	  	null,                          /*4、实际口 */
		  @BCR_NO,                           /*5、读码器 */
		  NULL,                           /*6、分拣状态 */
		  @sCODE,                        /*7、执行代码 */
	  	@LOG,                           /*8、执行信息 */
		  'sp_hc46_shopee_scan_rev',       /*9、执行过程 */
		  @v_s,                           /*10、执行时间 */
	  	'hc46',                          /*11、dvc编号 */  
	  	@p_send,                      			/*12、备用1 */   
	  	@p_Rev,                           /*13、备用2 */
	  	@P_msg,                         /*14、备用3 */
		  NULL,                           /*15、任务状态 */  
		  NULL,		                        /*16、上车状态 */
			null                           /*16、wcs任务号 */                       
	END
