-- ----------------------------
DROP PROCEDURE [sp_hc53_shopee_upload_image_rev]
GO

CREATE PROCEDURE [sp_hc53_shopee_upload_image_rev] /*多件格口释放接收 */
  @p_uuid varchar(100),  
	@p_Send VARCHAR(4000),
  @p_Rev VARCHAR(4000),
  @P_CODE VARCHAR(100) OUT,
  @P_MSG VARCHAR(4000) OUT
AS
  declare @taskNo varchar(400)='',@curAddress varchar(100)=''
	  ,@barcode varchar(4000),@wcsTaskNum varchar(50) 
		,@containerType varchar(40),@code varchar(200)=''
		,@jsonSend varchar(4000),@containerCode varchar(200)
		,@pointCode	varchar(100),@scan_id varchar(200)		
  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN
	BEGIN TRY		
		/*set @code = json_value(@p_Rev,'$.code')	  */
		set @code = json_value(@p_Rev,'$.retcode')	  
		set @P_CODE ='0'
	end try
	BEGIN CATCH
  END CATCH	
	if isnull(@code,'')='0'
	begin			  
	  set @jsonSend = substring(@p_send,charindex('#####',@p_send)+len('#####'),4000)	
			
		/*set @wcsTaskNum = json_value(@jsonSend,'$.data[0].wcsTaskNum')				 */
	  /*set @p_msg='[wcs->hiwms]cancelWcsTask,wcsTaskNum:'+isnull(@wcsTaskNum,'')		 */
		  
		select @barcode=barcode,@scan_id=scan_id from wcs_tools_feedback where id=@p_uuid 
			
		/*set @wcsTaskNum = json_value(@jsonSend,'$.data[0].wcsTaskNum')				 */
	  set @p_msg='[tws_img]'+isnull(@barcode,'')+',scan_id:'+isnull(@scan_id,'')+',Online image upload successful'
		  
		delete from wcs_tools_feedback where id=@p_uuid 	
		
		SET @v_s    = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100
		EXEC [dbo].[sp_create_wcs_log]
	  	'tws_img',            /*1、作业名称 */
	  	@barcode,                   /*2、容器号 */
	  	null,                   /*3、应去口 */
	  	null,                          /*4、实际口 */
		  NULL,                           /*5、读码器 */
		  NULL,                           /*6、分拣状态 */
		  @P_CODE,                        /*7、执行代码 */
	  	@p_msg,                           /*8、执行信息 */
		  'sp_hc53_shopee_upload_image_rev',       /*9、执行过程 */
		  @v_s,                           /*10、执行时间 */
	  	'hc4',                          /*11、dvc编号 */  
	  	@p_Rev,                      			/*12、备用1 */   
	  	@p_Send,                           /*13、备用2 */
	  	null,                         /*14、备用3 */
		  null,                           /*15、任务状态 */  
		  NULL,		                        /*16、上车状态 */
			null                           /*16、任务号 */   
	end
	else
	begin
	 
	  /* 失败分支：累加重试次数，并根据次数决定下一次的状态 */
      DECLARE @current_retry INT;
      
      /* 获取累加后的当前重试次数 */
      SELECT @current_retry = isnull(retry_count, 0) + 1 
      FROM wcs_tools_feedback 
      WHERE id = @p_uuid;

      IF @current_retry >= 3
      BEGIN
          /* 已经重试 3 次仍然失败：将 flag 置为 '2' (表示永久失败)，退出重试队列 */
          /*UPDATE wcs_tools_feedback 
          SET flag = '2', retry_count = @current_retry 
          WHERE id = @p_uuid;   */    
					INSERT INTO wcs_tools_feedback_bak( type,flag,barcode,curAddress,create_date,update_date,url,scan_id,sort_time,ParcelID,retry_count) 
            select type,'2',barcode,curAddress,create_date,update_date,url,scan_id,sort_time,ParcelID,3 from wcs_tools_feedback where id=@p_uuid   
          delete from wcs_tools_feedback where id = @p_uuid
      END
      ELSE
      BEGIN
          /* 未达到 3 次：将 flag 还原为 '0' 等待下一次被抓取重发，更新重试次数 */
          UPDATE wcs_tools_feedback 
          SET flag = '0', retry_count = @current_retry 
          WHERE id = @p_uuid;
      END
		  
	end
END

GO

