CREATE PROCEDURE [sp_hc53_shopee_upload_image_send] /*多件集货完成 */
  @P_uuid VARCHAR(4000) OUT,
	@p_Send VARCHAR(4000) OUT,
  @P_CODE VARCHAR(100) OUT,
  @P_MSG VARCHAR(4000) OUT
AS
 /*向wms发送   设备状态回传接口*/
	DECLARE @header VARCHAR(4000) = '';/*设置的头*/
	DECLARE @body VARCHAR(4000) = '';/*发送的body*/
	DECLARE @body1 VARCHAR(4000) = '';/*发送的body*/
	DECLARE @id varchar(100)
/*	DECLARE @url VARCHAR(1000) = '/openapi/transport/asm_api/v1/single_receive'       */
  declare @uuid varchar(100),@url VARCHAR(1000),@scan_id varchar(1000)
  declare @timestamp varchar(100),@ParcelID int

  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN 
  set @p_uuid=''
  set @p_send=''
  
  select top 1 @id=id,@scan_id=scan_id,@url=url,@ParcelID = ParcelID
	 from wcs_tools_feedback where type='img_upload'
	 and isnull(retry_count, 0) < 3 /* 增加此条件：拦截重试已经达到或超过 3 次的异常数据 */ 
	   order by create_date asc
  IF @@rowcount=1
  BEGIN 
    update wcs_tools_feedback set flag='1' where id=@id
  
    set @uuid = LOWER(REPLACE(CAST(NEWID() AS VARCHAR(36)), '-', ''))
    set @timestamp = DATEDIFF(SECOND, '1970-01-01 00:00:00', GETUTCDATE())
  
    set @body1= '{
    "data": {
    "scan_id" : '+isnull(@scan_id,'')+',
    "access_token":"'+dbo.f_tools_mem('wms_access_token')+'",
    "image_type" : "JPEG",
    "machine_id": "'+dbo.f_tools_mem('wms_machine_id')+'",
    "whs_id": "'+dbo.f_tools_mem('wms_whs_id')+'",
    "request_id": "'+isnull(@uuid,'')+'",
    "lang": "ZH"
    },
    "timestamp": '+isnull(@timestamp,'')+'
    }'

    set @header= 'jwt@@'+'{$SHOPEE2;HS256;'+dbo.f_tools_mem('wms_jwt_account')+';'+dbo.f_tools_mem('wms_jwt_secret')+';'+isnull(@body1,'')+'$}' 
    /*set @body = 'file@@d:/img/200.jpg'  */
    set @url='d:/img'+isnull(@url,'')+'/SC01_'
		  +isnull(LEFT(
        RIGHT(@url, CHARINDEX('/', REVERSE(@url)) - 1), 
        CHARINDEX('_', RIGHT(@url, CHARINDEX('/', REVERSE(@url)) - 1)) - 1),'')
      +'_'+isnull(FORMAT(@ParcelID, '0000'),'')+'_'+RIGHT(@URL, 2)+'_'
			+ isnull(PARSENAME(REPLACE(@url, '_', '.'), 2),'')
			+ '_UP.jpg'
		
    set @body = 'file@@'+@url
    /*set @body = 'file@@d:/img/200.jpg'   */
    /*set @body = 'file@@d:/img/600,222.jpg'  */
	  		 		  
    set @p_send= isnull(@header,'')+'#####'+isnull(@body,'')
    set @p_uuid=@id
  end
END

