/* ==================================================================== */
/* 3. 上报收货拒绝接口 (对应文档 3.6.5. report_receiving_rejection) */
/* 业务场景：包裹在安检(DWS/Induction)被拒收，踢入异常槽时调用 */
/* ==================================================================== */
CREATE   PROCEDURE [sp_hc55_shopee_report_receiving_rejection_send] 
  @P_uuid VARCHAR(4000) OUT,
  @p_Send VARCHAR(4000) OUT,
  @P_CODE VARCHAR(100) OUT,
  @P_MSG VARCHAR(4000) OUT
AS
BEGIN 
  DECLARE @header VARCHAR(4000) = '';
  DECLARE @body VARCHAR(MAX) = '';
  
  /* 模拟业务变量 */
  DECLARE @v_from_entrance_id VARCHAR(50) = 'DWS_01';
  DECLARE @v_reject_chute_id VARCHAR(50) = 'Reject_Line_01';
  DECLARE @v_operator VARCHAR(100) = 'test@shopee.com';
  DECLARE @v_package_id VARCHAR(100) = 'SPXID88888888';
  DECLARE @v_reject_reason VARCHAR(100) = 'Weight Too Heavy'; /* 拒绝原因需符合文档 4.2.6 */
  DECLARE @v_scan_time INT = DATEDIFF(SECOND, '1970-01-01 00:00:00', GETUTCDATE());

  SET @p_uuid = '';

  set @header= 'Content-Type@@application/json;Authorization@@Bearer {$SHOPEE1;HS256;JWT;'+dbo.f_tools_mem('wms_jwt_account')+';'+dbo.f_tools_mem('wms_jwt_secret')+'$}'

  /* 拼接拒绝 JSON (注意外层是 list 数组) */
  SET @body = '{
  "list" : [
    {
      "from_entrance_type" : 2,
      "entrance_type" : 4,
      "from_entrance_id" : "' + @v_from_entrance_id + '",
      "entrance_id" : "Target_Chute",
      "from_operator" : "' + @v_operator + '",
      "operator" : "' + @v_reject_chute_id + '",
      "package_id" : "' + @v_package_id + '",
      "package_type" : 1,
      "time" : ' + CAST(@v_scan_time AS VARCHAR) + ',
      "reject_reason_type" : 2,
      "reject_reason" : "' + @v_reject_reason + '"
    }
  ]
}';

  SET @p_Send = ISNULL(@header,'') + '#####' + ISNULL(@body,'');
END



GO

