CREATE PROCEDURE [sp_hc57_shopee_scan_rev] /*多件格口释放接收 */
  @p_uuid varchar(100),  
	@p_Send VARCHAR(4000),
  @p_Rev VARCHAR(4000),
  @P_CODE VARCHAR(100) OUT,
  @P_MSG VARCHAR(4000) OUT
AS
  declare @taskNo varchar(400)='',@cur_pos varchar(100)=''
	  ,@wcsTaskNum varchar(50) 
		,@containerType varchar(40),@code varchar(200)=''
		,@jsonSend varchar(4000),@containerCode varchar(200)
		,@pointCode	varchar(100),@barcode varchar(200)	
  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN
	BEGIN TRY		
		set @code = json_value(@p_Rev,'$.retcode')	  
		set @P_CODE ='0'
	end try
	BEGIN CATCH
  END CATCH	
	if isnull(@code,'')='0'
	begin		  		  	 
		select @barcode=barcode from wcs_tools_feedback where id=@p_uuid 
			
		/*set @wcsTaskNum = json_value(@jsonSend,'$.data[0].wcsTaskNum')				 */
	  set @p_msg='[fms_scan]barcode:'+isnull(@barcode,'')+',Online scan upload successful'
		  
		delete from wcs_tools_feedback where id=@p_uuid 	 
		
		SET @v_s    = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100
		EXEC [dbo].[sp_create_wcs_log]
	  	'fms_scan',            /*1、作业名称 */
	  	@barcode,                   /*2、容器号 */
	  	null,                   /*3、应去口 */
	  	null,                          /*4、实际口 */
		  NULL,                           /*5、读码器 */
		  NULL,                           /*6、分拣状态 */
		  @P_CODE,                        /*7、执行代码 */
	  	@p_msg,                           /*8、执行信息 */
		  'sp_hc57_shopee_scan_rev',       /*9、执行过程 */
		  @v_s,                           /*10、执行时间 */
	  	'hc57',                          /*11、dvc编号 */  
	  	@p_Rev,                      			/*12、备用1 */   
	  	@p_Send,                           /*13、备用2 */
	  	null,                         /*14、备用3 */
		  null,                           /*15、任务状态 */  
		  NULL,		                        /*16、上车状态 */
			null                           /*16、任务号*/   
	end
	else
	begin
	  update wcs_tools_feedback set flag='0' where id=@p_uuid 
	end
END
GO

