CREATE PROCEDURE [sp_hc58_shopee_receiving_rejection_send] 
  /* 包裹扫描上报接口 (对应文档 3.6.1) */
  @P_uuid VARCHAR(4000) OUT,
	@p_Send VARCHAR(4000) OUT,
  @P_CODE VARCHAR(100) OUT,
  @P_MSG VARCHAR(4000) OUT
AS
 /*向wms发送   设备状态回传接口*/
	DECLARE @header VARCHAR(4000) = '';/*设置的头*/
	DECLARE @body VARCHAR(4000) = '';/*发送的body*/
	DECLARE @body1 VARCHAR(4000) = '';/*发送的body*/
	DECLARE @id varchar(100)
/*	DECLARE @url VARCHAR(1000) = '/openapi/transport/asm_api/v1/single_receive'       */
  declare @uuid varchar(100),@url VARCHAR(1000),@barcode varchar(1000)
  declare @scan_time varchar(50),@cur_pos varchar(50)
  declare @timestamp varchar(100),@times2 varchar(100),@reject_reason_type varchar(200)='2',
    @status varchar(20)

  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN 
  set @p_uuid=''
  set @p_send=''
  
  select top 1 @id=id,@barcode=barcode,@scan_time=sort_time,@cur_pos=curAddress,@status=status
	 from wcs_tools_feedback where type='sort_err' and flag='0' order by create_date asc
  IF @@rowcount=1
  BEGIN 
    update wcs_tools_feedback set flag='1' where id=@id
    set @times2 = DATEDIFF(SECOND, '1970-01-01 00:00:00', @scan_time)
    if len(@status)=3 set @reject_reason_type='1'
    
    set @header= 'Content-Type@@application/json;Authorization@@Bearer {$SHOPEE1;HS256;JWT;'+dbo.f_tools_mem('wms_jwt_account')+';'+dbo.f_tools_mem('wms_jwt_secret')+'$}'

 SET @body = '{
  "list" : [
    {
      "from_entrance_type" : 5,
      "entrance_type" : 4,
      "from_entrance_id" : "' + dbo.f_tools_mem('wms_machine_id') + '",
      "entrance_id" : "NBS",
      "from_operator" : "' + dbo.f_tools_mem('wms_account') + '",
      "operator" : "' + @cur_pos + '",
      "package_id" : "' + @barcode + '",
      "package_type" : 1,
      "time" : ' + @times2 + ',
      "reject_reason_type" : '+@reject_reason_type+',
      "reject_reason" : "' + isnull(dbo.f_tools_mem('fms_plc_state_'+@status),'')  + '"
    }
  ]
}'
    set @p_send= isnull(@header,'')+'#####'+isnull(@body,'')
    set @p_uuid=@id
  end
END
