-- ----------------------------
DROP PROCEDURE [sp_hc64_shopee_to_pack_rev]
GO
CREATE PROCEDURE [sp_hc64_shopee_to_pack_rev] /*多件格口释放接收 */
  @p_uuid varchar(100),  
	@p_Send VARCHAR(4000),
  @p_Rev VARCHAR(max),
  @P_CODE VARCHAR(100) OUT,
  @P_MSG VARCHAR(4000) OUT
AS
  declare @cur_pos varchar(100)=''
		,@code varchar(200)='',@shipment_id varchar(200)	
  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
  declare @to varchar(50),@print_data_zpl varchar(4000)
BEGIN
	BEGIN TRY		
		set @code = json_value(@p_Rev,'$.retcode')	  
		set @P_CODE ='0'
	end try
	BEGIN CATCH
  END CATCH	
	if isnull(@code,'')='0'
	begin		  		  	 
		select @cur_pos=curAddress from wcs_tools_feedback where id=@p_uuid 

	  SELECT @to=StringValue 
      FROM f_tools_parseJSON(@p_Rev)
      WHERE NAME = 'transport_order_number'	
      
    SELECT @print_data_zpl=StringValue 
      FROM f_tools_parseJSON(@p_Rev)
      WHERE NAME = 'print_data_zpl'
      
    update wcs_tools_label set Last_TO=@to,receiver_name='',sort_code=''
		  ,last_zpl=@print_data_zpl,parcel_num=0 
		  where wms_to_pos=isnull(@cur_pos,'')
		
		INSERT INTO wcs_tools_hand_cmd( dvc_no,cmd_name,cmd) 
		  VALUES (dbo.f_tools_mem('print_chute_'+@cur_pos),'print_'+@to,@print_data_zpl)
																																		 	 
	  set @p_msg='[fms_pack]'+isnull(@cur_pos,'')+',to:'+isnull(@to,'')+',got zpl successful'
		  
		delete from wcs_tools_feedback where id=@p_uuid 	 
		
		SET @v_s    = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100
		EXEC [dbo].[sp_create_wcs_log]
	  	'fms_pack',            /*1、作业名称 */
	  	null,                   /*2、容器号 */
	  	null,                   /*3、应去口 */
	  	@cur_pos,                          /*4、实际口 */
		  NULL,                           /*5、读码器 */
		  NULL,                           /*6、分拣状态 */
		  @P_CODE,                        /*7、执行代码 */
	  	@p_msg,                           /*8、执行信息 */
		  'sp_hc64_shopee_to_pack_rev',       /*9、执行过程 */
		  @v_s,                           /*10、执行时间 */
	  	'hc64',                          /*11、dvc编号 */  
	  	@p_Rev,                      			/*12、备用1 */   
	  	@p_Send,                           /*13、备用2 */
	  	null,                         /*14、备用3 */
		  null,                           /*15、任务状态 */  
		  NULL,		                        /*16、上车状态 */
			null                           /*16、任务号*/   
	end
	else
	begin
	  update wcs_tools_feedback set flag='0' where id=@p_uuid 
	end
END
