-- ----------------------------
-- Procedure structure for sp_hc72_shopee_scan_rev
-- ----------------------------
DROP PROCEDURE [sp_hc72_shopee_scan_rev]
GO

CREATE PROCEDURE [sp_hc72_shopee_scan_rev] /*多件格口释放接收 */
  @p_uuid varchar(100),  
	@p_Send VARCHAR(4000),
  @p_Rev VARCHAR(4000),
  @P_CODE VARCHAR(100) OUT,
  @P_MSG VARCHAR(4000) OUT
AS
  declare @scan_id varchar(400)='',@url varchar(2000)=''
	  ,@barcode varchar(4000)
		,@jsonSend varchar(4000),@parcelId int
  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN
  set @P_CODE ='0'
	BEGIN TRY		
		SELECT @scan_id=scan_id FROM (SELECT a.parent_ID, a.NAME, a.StringValue
          FROM   f_tools_parseJSON(@p_rev) a 
			      where a.parent_id ='2' and isnull(a.name,'')in('disp_info','sorting_direction','scan_id','scan_number') )t1
            PIVOT (MAX(StringValue) FOR NAME IN(disp_info,sorting_direction,scan_id,scan_number)) AS t2	 
	end try
	BEGIN CATCH
  END CATCH	
	if isnull(@scan_id,'')<>''
	begin	
    set @jsonSend = substring(@p_send,charindex('#####',@p_send)+len('#####'),4000)	
			
	  select @barcode=barcode from wcs_tools_feedback where id=@p_uuid 
		select @url=url,@parcelId=parcelId from wcs_task where task_type='offline' and barcode = isnull(@barcode,'')	   	  		  		  
		insert into wcs_tools_feedback(scan_id,url,barcode,type,flag,parcelId)
		  values(@scan_id,@url,@barcode,'img_upload_offline','0',@parcelId)  
			
		/*set @wcsTaskNum = json_value(@jsonSend,'$.data[0].wcsTaskNum')				 */
	  set @p_msg='[scan_offline]barcode:'+isnull(@barcode,'')+',scan_id:'+isnull(@scan_id,'')+',Offline scan upload successful'	  
		delete from wcs_tools_feedback where id=@p_uuid 				
		SET @v_s    = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100
		EXEC [dbo].[sp_create_wcs_log]
	  	'scan_offline',            /*1、作业名称 */
	  	@barcode,                   /*2、容器号 */
	  	null,                   /*3、应去口 */
	  	null,                          /*4、实际口 */
		  NULL,                           /*5、读码器 */
		  NULL,                           /*6、分拣状态 */
		  @P_CODE,                        /*7、执行代码 */
	  	@p_msg,                           /*8、执行信息 */
		  'sp_hc72_shopee_scan_rev',       /*9、执行过程 */
		  @v_s,                           /*10、执行时间 */
