  @P_CODE VARCHAR(100) OUT,
  @P_MSG VARCHAR(4000) OUT
AS
  declare @scan_id varchar(400)='',@cur_pos varchar(100)=''
	  ,@barcode varchar(4000)
		,@jsonSend varchar(4000),@update_date date	
  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN
	BEGIN TRY		
		/*set @code = json_value(@p_Rev,'$.code')	  */
		set @P_CODE ='0'
	end try
	BEGIN CATCH
  END CATCH	
	if isnull(@p_Rev,'')<>''
	begin		   		  
	  set @jsonSend = substring(@p_send,charindex('#####',@p_send)+len('#####'),4000)	
			
		select @barcode=barcode,@scan_id=scan_id from wcs_tools_feedback where id=@p_uuid 
		select @cur_pos=cur_pos,@update_date=update_date from wcs_task where task_type='offline' and barcode = isnull(@barcode,'')	   	  		  		  
		insert into wcs_tools_feedback(scan_id,curAddress,sort_time,type,flag)
		  values(@scan_id,@cur_pos,@update_date,'sort_offline','0')  
			
		/*set @wcsTaskNum = json_value(@jsonSend,'$.data[0].wcsTaskNum')				 */
	  set @p_msg='[img_offline]barcode:'+isnull(@barcode,'')+',scan_id:'+isnull(@scan_id,'')+',Offline image upload successful'
		
		delete from wcs_tools_feedback where id=@p_uuid 	
		SET @v_s    = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100
		EXEC [dbo].[sp_create_wcs_log]
	  	'img_offline',            /*1、作业名称 */
	  	null,                   /*2、容器号 */
	  	null,                   /*3、应去口 */
	  	null,                          /*4、实际口 */
		  NULL,                           /*5、读码器 */
		  NULL,                           /*6、分拣状态 */
		  @P_CODE,                        /*7、执行代码 */
	  	@p_msg,                           /*8、执行信息 */
		  'sp_hc53_shopee_upload_image_rev',       /*9、执行过程 */
		  @v_s,                           /*10、执行时间 */
	  	'hc4',                          /*11、dvc编号 */  
	  	@p_Rev,                      			/*12、备用1 */   
	  	@p_Send,                           /*13、备用2 */
	  	null,                         /*14、备用3 */
		  null,                           /*15、任务状态*/  
		  NULL,		                        /*16、上车状态 */
			null                           /*16、任务号 */   
	end
	else
	begin
	  update wcs_tools_feedback set flag='0' where id=@p_uuid 
	end
END

