  DECLARE @v_DATE1 DATETIME = GETDATE(), @v_s INT = 0;
BEGIN 
  set @p_uuid=''
  set @p_send=''
  
  select top 1 @id=id,@scan_id=scan_id,@url=url,@ParcelID = ParcelID
	 from wcs_tools_feedback where type='img_upload_offline' and flag='0' order by create_date asc
  IF @@rowcount=1
  BEGIN 
    update wcs_tools_feedback set flag='1' where id=@id
  
    set @uuid = LOWER(REPLACE(CAST(NEWID() AS VARCHAR(36)), '-', ''))
