  @P_dvc_no VARCHAR(20),  /*PLC的dvc_no*/
  @p_REV VARCHAR(4000),  /*接收到的报文*/
  @P_SEND VARCHAR(4000) OUT,  /*回复ACK和报文*/
  @p_Pack_Nr INT OUT,  /*上一次数据包序号*/
  @P_CODE VARCHAR(20) OUT,
  @P_MSG VARCHAR(4000) OUT  /*显示在mem的信息*/
AS
  declare @v_AlarmMsg varchar(100),@err varchar(50),@err_all varchar(200)
BEGIN
	update wcs_dvc set UPDATE_DATE=convert(varchar,GETDATE(),120) where dvc_no= @P_dvc_no  
  IF @p_REV in('register_online','register_offline')
    BEGIN
      SET @P_SEND = '';
      SET @P_MSG  = '';
      RETURN;
    END
    
  set @v_AlarmMsg= dbo.f_tools_Hex_To_Char(@p_rev)
  while charindex('1',@v_AlarmMsg) !=0
  begin
    declare @index1 int=charindex('1',@v_AlarmMsg)
    set @err = dbo.f_tools_mem('label_error_code_E'+cast(@index1 as varchar))    
    set @err_all = isnull(@err_all,'') +'&&'+ isnull(@err,'') 
    set @v_AlarmMsg= stuff(@v_AlarmMsg,@index1,1,'0')
  end

  SET @P_CODE      = '0'
  SET @P_SEND      = ''
  if isnull(@err_all,'')!='&&'
    SET @P_MSG       = '[label_rev]'+ @err_all

END
GO

