-- ----------------------------
-- Procedure structure for sp_plc_relay_request
-- ----------------------------
DROP PROCEDURE [sp_plc_relay_request]
GO

CREATE PROCEDURE [sp_plc_relay_request]/*接力拣选*/
	@P_BARCODE VARCHAR(100),/*条码 */
	@P_BCR VARCHAR(50),/*bcr */
	@P_Destination VARCHAR(50) OUT,/*地址，plc的 */
	@pos varchar(50) out
AS
	DECLARE @cursor   CURSOR  /*游标 */
	DECLARE @CONT_NO  VARCHAR(200) = ''/*条码*/
	DECLARE @TO_POS   VARCHAR(200) = ''/*去向*/
	DECLARE @TO_POS2   VARCHAR(200) = ''/*去向*/	
	BEGIN
		SET @cursor =  CURSOR FOR 		
		SELECT barcode,
		       dbo.f_tools_WcsToPlc(TO_POS),to_pos
		FROM   wcs_task
		WHERE  barcode=@P_BARCODE and task_type='cv'
		ORDER BY
		       TO_POS ASC
		
		OPEN @cursor
		FETCH NEXT FROM @cursor INTO @CONT_NO,@TO_POS,@TO_POS2
		WHILE @@FETCH_STATUS = 0
		BEGIN
				set @pos = @TO_POS2
		    SELECT @P_Destination = plc_to_pos
		    FROM   wcs_guide_config A
		    WHERE  A.GUIDE = @P_BCR
		           AND A.wcs_to_pos LIKE '%'+@TO_POS+'%'
		    IF @@rowcount = 1
		        RETURN
		    
		    FETCH NEXT FROM @cursor INTO @CONT_NO,@TO_POS,@TO_POS2
		END
		CLOSE @cursor
		DEALLOCATE @cursor
		
	END



GO

-- ----------------------------
-- Procedure structure for sp_plc_report_sort
-- ----------------------------
DROP PROCEDURE [sp_plc_report_sort]
GO

CREATE PROCEDURE [sp_plc_report_sort] 
  @p_dvc_id VARCHAR(50),  /*plc编号*/
  @p_REV VARCHAR(4000) , 
  @P_SEND VARCHAR(4000) OUT,
  @p_CODE VARCHAR(20) OUT,
  @p_MSG VARCHAR(400) OUT
AS
DECLARE @SortResult VARCHAR(20),@SortResult_Msg VARCHAR(20),@AaasgnDest01 VARCHAR(20),@ExecuteDest VARCHAR(20)
       ,@SORTREASON VARCHAR(20),@SORTREASON_MSG VARCHAR(200),@BARCODE VARCHAR(500),@CUR_POS VARCHAR(50)
       ,@wms_to_pos VARCHAR(20) = '',@type VARCHAR(50),@BCR_NO VARCHAR(10),@barcode_len int
DECLARE @v_s INT = 0,@v_DATE1 DATETIME = GETDATE()
DECLARE @offset INT /* 用于计算条码后面动态字段的十六进制字符偏移量 */
declare @weight varchar(20),@volume varchar(20),@length varchar(20),@width varchar(20),@height varchar(20)
BEGIN
  SET @p_code = '0'

  BEGIN TRY
    /* 1. 解析条码之前的固定位置字段 (按 v8.1: 包裹号4字节导致整体后移) */
    SET @BCR_NO      = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 37, 4)) AS VARCHAR)  /* 读码器 (18~19字节) */
    SET @barcode_len = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 45, 4))                   /* 条码长度 (22~23字节) */
    
    /* 2. 解析动态长度的条码 */
    /* 从第 49 个字符(第24字节)开始截取，长度为 barcode_len * 2 */
    SET @BARCODE     = RTRIM(dbo.f_tools_Hex_To_Char(REPLACE(SUBSTRING(@p_rev, 49, @barcode_len*2), '00', ''))) 

    /* 3. 解析条码之后的动态位置字段 */
    /* 动态起点 = 条码起点(49) + 条码所占字符数(@barcode_len*2) */
    SET @offset = 49 + @barcode_len * 2
    
    SET @SortResult   = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, @offset, 4)) AS VARCHAR)      /* 分拣状态/结果 */
    SET @AaasgnDest01 = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, @offset + 4, 4)) AS VARCHAR)  /* 计划格口 */
    SET @ExecuteDest  = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, @offset + 8, 4)) AS VARCHAR)  /* 实际格口 */
    SET @SORTREASON   = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, @offset + 12, 4)) AS VARCHAR) /* 异常原因 */

    SET @type        = 'cv_report'
    SET @CUR_POS     = dbo.f_tools_PlcToWcs(@ExecuteDest);
        
    IF isnull(@CUR_POS,'') <> ''    
    BEGIN    
      UPDATE wcs_task SET cur_pos=@CUR_POS, update_date = GETDATE() WHERE barcode=@BARCODE AND task_type='cv'   /*更新当前口 */
      
      SET @p_Msg = 
          '[cv_report_sort]' + @BARCODE 
          + ',cur_pos:' + isnull(@ExecuteDest,'') + '(' + @CUR_POS + ')' 
          + isnull(@p_MSG,'')
          + '__SortResult:' + isnull(@SortResult, '')
          + ';AaasgnDest01:' + isnull(@AaasgnDest01, '')
          + ';ExecuteDest:' + isnull(@ExecuteDest, '')
          + ';SortReason:' + isnull(@SORTREASON, '') 
          + ';TrackID:' + CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 21, 4)) AS VARCHAR)   /* 21~24 对应小车号 */
          + ';ParcelID:' + CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 25, 8)) AS VARCHAR)  /* 25~32 对应包裹号 */
          + ';' + CAST(@p_dvc_id AS VARCHAR)    
    END 
    ELSE
    BEGIN
      /*转向口*/
      SET @p_Msg =
          'cv_report_turning:' 
          + isnull(@CUR_POS, '') + '[' + isnull(@ExecuteDest, '') + '] OR  ' + isnull(@wms_to_pos, '')
          + '[' + isnull(@AaasgnDest01, '') + ']' + 'no pos,barcode：' + @BARCODE 
          + '__SortResult:' + isnull(@SortResult, '')
          + ';AaasgnDest01:' + isnull(@AaasgnDest01, '')
          + ';ExecuteDest:' + isnull(@ExecuteDest, '') 
          + ';SortReason:' + isnull(@SORTREASON, '') 
          + ';TrackID:' + CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 21, 4)) AS VARCHAR) 
          + ';ParcelID:' + CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 25, 8)) AS VARCHAR)
          + ';' + CAST(@p_dvc_id AS VARCHAR)  
    END                                                                             
  END TRY
  BEGIN CATCH
    SELECT @p_code = ERROR_NUMBER(), @p_msg  = '分拣报告：' + ERROR_MESSAGE()
  END CATCH

  SET @v_s = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100
  SET @p_msg = isnull(@p_msg,'') + ',work_sec:' + CAST(@v_s AS VARCHAR(10))
  
  EXEC [dbo].[sp_create_wcs_log]
    @type,                        /*1、作业名称 */
    @BARCODE,                     /*2、容器号 */
    NULL,                         /*3、应去口 */
    @CUR_POS,                     /*4、实际口 */
    @BCR_NO,                      /*5、读码器 */
    @SORTREASON,                  /*6、分拣状态 (记录异常原因) */
    @P_CODE,                      /*7、执行代码 */
    @p_msg,                       /*8、执行信息 */
    'sp_plc_report_sort',         /*9、执行过程 */
    @v_s,                         /*10、执行时间 */
    @P_dvc_id,                    /*11、dvc编号 */  
    @p_REV,                       /*12、备用1 */
    NULL,                         /*13、备用2 */
    NULL,                         /*14、备用3 */
    NULL,                         /*15、任务状态 */  
    NULL,                         /*16、上车状态 */ 
    NULL                          /*17、任务号 */                       
END

GO

-- ----------------------------
-- Procedure structure for sp_plc_request_dest
-- ----------------------------
DROP PROCEDURE [sp_plc_request_dest]
GO

CREATE PROCEDURE [sp_plc_request_dest] 
  @P_dvc_id VARCHAR(20), @P_REV VARCHAR(4000), @P_SEND VARCHAR(4000) OUT, @P_CODE VARCHAR(10) OUT, @P_MSG VARCHAR(4000) OUT
AS
DECLARE @Tel_Head VARCHAR(10) = 'FCFC',/*小包起始符（FCFC）*/@Tel_End VARCHAR(10) = 'FDFD'  /*小包结束符（FDFD）*/
DECLARE @ParcelID VARCHAR(10),@Barcode VARCHAR(500),@Destination01 VARCHAR(50),@BCR_NO VARCHAR(10)
DECLARE @TO_POS VARCHAR(50),@NO_EXCEPTION_NO VARCHAR(20),@ERR_EXCEPTION_NO VARCHAR(20)
DECLARE @v_s INT = 0,@v_DATE1 DATETIME = GETDATE()
DECLARE @barcode_len int,@v_msg varchar(4000)/*hc的报文 */;

declare @weight int,@width int,@length int,@height int,@volume int,
  @send varchar(4000),@send2 varchar(4000),@url varchar(1000),
  @tel_sn varchar(20),@DestAmount int,@DestArr varchar(200), @tel_length int  
declare @id1 varchar(200),@pos2 varchar(50)
BEGIN
  SET @P_SEND = ''
  SET @P_CODE = '0'
  SET @P_MSG  = ''

  BEGIN TRY
/* 1. 小报文长度 (2 Bytes: Byte 4) */
    SET @tel_sn = SUBSTRING(@p_REV, 9, 4)
/* 2. 包裹号 (4 Bytes: Byte 12)  <- 修正: 原为 17,4，应为 25,8 */
    SET @ParcelID = SUBSTRING(@p_REV, 25, 8)
/* 3. 读码器 (2 Bytes: Byte 18)  <- 修正: 原为 21,4，应为 37,4 */
    SET @BCR_NO = CAST(dbo.f_tools_hextoint(SUBSTRING(@p_REV, 37, 4)) AS VARCHAR)
/* 4. 条码长度 (2 Bytes: Byte 22) <- 修正: 原为 25,4，应为 45,4 */
    SET @barcode_len = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 45, 4))
/* 5. 条码内容 (x Bytes: Byte 24) <- 修正: 起始索引应为 49 */
    SET @Barcode = dbo.f_tools_HEX_TO_CHAR(SUBSTRING(@p_REV, 49, @barcode_len * 2))
/* 6. 货物长度 (2 Bytes: Byte 28+x) <- 修正: 起始索引应为 57 + len*2 */
    SET @length = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 57 + @barcode_len * 2, 4)) 
/* 7. 货物宽度 (2 Bytes: Byte 30+x) <- 修正: 起始索引应为 61 + len*2 */
    SET @width = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 61 + @barcode_len * 2, 4)) 
/* 8. 货物高度 (2 Bytes: Byte 32+x) <- 修正: 起始索引应为 65 + len*2 */
    SET @height = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 65 + @barcode_len * 2, 4))
/* 9. 货物重量 (4 Bytes: Byte 34+x) <- 修正: 起始索引应为 69 + len*2，截取8个字符 */
    SET @weight = dbo.f_tools_hextoint(SUBSTRING(@p_REV, 69 + @barcode_len * 2, 8))
		/*SET @weight = round(isnull(@weight, 0) / 1000.0, 2) */					
		set @url=''

		/*查询扫码器配置表中该扫码器是否为实时请求扫码器,hc1四面扫 hc2换箱  hc3容器申请   hc4任务取消  hc5重量上报  hc6任务分流  0代表非实时请求  7接力拣选*/
		IF isnull(dbo.f_tools_mem('bcr_type_'+@BCR_NO),'') in ('6') 
		  AND  @Barcode NOT IN ('','??????????', 'NoRead','NG','!!!!!') 
			AND isnull(dbo.f_tools_mem('sort_mode'),'') in ('1')
		BEGIN	
		  /*一层任务分流																		 								   */
			SET @p_msg = isnull(@Barcode ,'') + ',post wms'																				 								 																		 																																																															 		 					 
			exec sp_plc_make_wms_msg '6',@Barcode,@weight,@length,@width,@height,@send out
			set @p_send= '~~hc46&='+@send 																																																																																														 								 																		 																																																															 		 					 
																																																																																																																																																																																																	 																																																																																																 								 																		 																																																															 		 					 
    	DELETE FROM wcs_tools_parcel	WHERE ParcelID=@ParcelID	AND	type='cv'											 																										          
			INSERT INTO wcs_tools_parcel(barcode,type,status,ParcelID,msg,bcr,dvc_no,tel_sn,url) 
			  VALUES (@Barcode,'cv','0',@ParcelID,isnull(@send,''),@BCR_NO,@P_dvc_id,@tel_sn,@url)	
		END
		else
		begin		
			/*非实时请求 */
		  set @NO_EXCEPTION_NO=	dbo.f_tools_mem('bcr_no_'+@BCR_NO)
			set @ERR_EXCEPTION_NO= dbo.f_tools_mem('bcr_err_'+@BCR_NO)				    	

	  	IF @Barcode IN ('','??????????', 'NoRead','NG','!!!!!') 
	    BEGIN
		    SET @TO_POS = @ERR_EXCEPTION_NO
		    SET @p_msg    = 'NOREAD,ToPos:'
  	  END
	    ELSE
	    BEGIN
			  SELECT top 1 @TO_POS = TO_POS
			  FROM wcs_task WHERE barcode=@Barcode and task_type='cv'

	  	 	IF @@rowcount = 1
	    	BEGIN 				  																			 		 							 											 			 																																																																																																																																																																																																																																																																																																																																																			 			      
			    SET @p_Msg = isnull(@Barcode,'')+',ToPos:'
		    END
	    	ELSE
	  	 	BEGIN
			 	  SET @p_msg    = isnull(@Barcode,'')+',NoTask,ToPos:'
			 	  SET @TO_POS = @NO_EXCEPTION_NO
	    	END
	    end      										 																																								 																																			
	    		 		 					    
			if isnull(@P_SEND,'')=''/*多目的地区分 */
      begin        
        EXEC [dbo].[sp_tools_Guide]  /*输送线转移口处理*/
										 @TO_POS, @BCR_NO, @Destination01 OUTPUT										 																																																																																																																																																																																																																																																																																																																																																																																																 				 					
			
        SET @P_SEND = @Tel_Head + '0800'+@tel_sn+RIGHT(dbo.f_tools_inttohex(20+2+@barcode_len+2), 4)+ @ParcelID + '00000000'
				  +RIGHT(dbo.f_tools_inttohex(@barcode_len), 4)+SUBSTRING(@p_rev, 29, @barcode_len*2)+'0001'+ RIGHT(dbo.f_tools_inttohex(@Destination01), 4)	
					+SUBSTRING(@p_REV, 48+@barcode_len*2+1, 4)+SUBSTRING(@p_rev, 52+@barcode_len*2+1, 2)+@Tel_End
			end			 														       	
		END	
		
		SET @p_msg ='[cv_request]' + isnull(@p_msg,'') + ISNULL(@Destination01,'') 
						+ ',Bcr' + @BCR_NO + ',length-width-height='+cast(@length as varchar)+'-'+cast(@width as varchar)+'-'+cast(@height as varchar)
						+ ',weight='++cast(@weight as varchar)
						+',id:' + CAST(dbo.f_tools_hextoint(@ParcelID) AS VARCHAR) 		  	
		
  END TRY
  BEGIN CATCH
    SELECT @p_code = ERROR_NUMBER(), @p_msg  = '目的地请求错误：' + ERROR_MESSAGE()
  END CATCH

  SET @v_s    = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100
  set @p_msg = isnull(@p_msg,'')+',work_sec:'+cast(@v_s as varchar(10))
  EXEC [dbo].[sp_create_wcs_log]
	  	'cv_request',              /*1、作业名称 */
	  	@Barcode,                     /*2、容器号 */
	  	null,                           /*3、应去口 */
	  	NULL,                           /*4、实际口 */
		  @BCR_NO,                      /*5、读码器 */
		  NULL,                           /*6、分拣状态 */
		  @P_CODE,                        /*7、执行代码 */
	  	@p_msg,                         /*8、执行信息 */
		  'SP_PLC_REQUEST_DEST',          /*9、执行过程 */
		  @v_s,                           /*10、执行时间 */
	  	@P_dvc_id,                      /*11、dvc编号 */  
	  	@p_REV,                         /*12、备用1 */
	  	@P_SEND,                         /*13、备用2 */
	  	null,                           /*14、备用3 */
		  NULL,                           /*15、任务状态 */  
		  null,	                        /*16、上车状态 */
			null                           /*16、任务号 */
END

GO

-- ----------------------------
-- Procedure structure for sp_sd_bcr_msg_rev
-- ----------------------------
DROP PROCEDURE [sp_sd_bcr_msg_rev]
GO

CREATE PROCEDURE [sp_sd_bcr_msg_rev]  
  @P_dvc_no VARCHAR(20),  /*PLC的dvc_no*/
  @p_REV VARCHAR(4000),  /*接收到的报文*/
  @P_SEND VARCHAR(4000) OUT,  /*回复ACK和报文*/
  @p_Pack_Nr INT OUT,  /*上一次数据包序号*/
  @P_CODE VARCHAR(20) OUT,
  @P_MSG VARCHAR(400) OUT  /*显示在mem的信息*/
  /*<1,2,3,4,5,6,7><21,22,23,24,25,26,27> */
AS
DECLARE @v_Pack_Head VARCHAR(10) = '';  /*起始符（4个FE）*/
DECLARE @v_Pack_End VARCHAR(10) = '';  /*结尾符（4个FF）*/
DECLARE @v_Temp_Pack VARCHAR(4000) = '';  /*临时大包信息*/
DECLARE @v_Temp_Pack_Msg VARCHAR(4000) = '';  /*大包中的小包信息*/
DECLARE @v_Temp_Tel VARCHAR(4000) = '';  /*临时小包信息*/

DECLARE @V_DATE1 DATETIME=GETDATE();
DECLARE @v_s INT = 0;

	DECLARE @s_header VARCHAR(4000) = '';/*设置的头*/
	DECLARE @s_body VARCHAR(4000) = '';/*发送的body*/
	DECLARE @serviceName VARCHAR(400) = '';/*接口地址*/
	DECLARE @methodName VARCHAR(400) = '';/*接口名*/
	DECLARE @data VARCHAR(4000) = '';/*数据*/
	
	declare @TRACK_ID varchar(100),/*小车号, */
	 @BCR_NO varchar(100),/*读码器编号  */
	 @InductionNO varchar(100),/*上包台编号  */
	 @Loops int,/*圈数 */
	 @Barcode1 varchar(500),/*条码 */
	 @Barcode2 varchar(500),/*条码2 */
	 @wmsUUID varchar(100),
	 @v_msg varchar(4000);/*hc的报文 */

BEGIN
  SET @P_CODE      = '0'
  SET @P_SEND      = ''
  SET @P_MSG       = ''
  SET @V_DATE1     = GETDATE();
  SET @v_Pack_Head = '<';
  SET @v_Pack_End  = '>';
  
  IF @p_REV = 'register_online'
    BEGIN
      SET @P_SEND = '';
      SET @P_MSG  = '';
      RETURN;
    END
    
  SET @v_Temp_Pack = dbo.f_tools_HEX_TO_CHAR(@p_REV);
  /*select @v_Temp_Pack */
 /* select 1 */
  WHILE @v_Temp_Pack <> ''
  BEGIN  
    SET @v_Temp_Pack_Msg = SUBSTRING(@v_Temp_Pack, 2, CHARINDEX(@v_Pack_End, @v_Temp_Pack, 2) - 2)
    /*select '@v_Temp_Pack_Msg='+@v_Temp_Pack_Msg */
    /*小包处理*/
    SET @v_Temp_Tel   = @v_Temp_Pack_Msg;
    if @v_Temp_Tel not like '%HHBB%'
    begin
		if (object_id('tempdb..#ITEM') is not null) drop table #ITEM /*删除临时表 */
		SELECT * INTO #ITEM
			FROM   dbo.f_tools_splitSTR(@v_Temp_Tel, ',')						 
					 
			DECLARE @i INT,@P_CNT INT
			select @P_CNT=count(1)   from #ITEM
			/*select '@P_CNT='+cast(@P_CNT as varchar) */
			SET @i = 1 
			WHILE @i <= @P_CNT
			BEGIN
					 /*1,2,3,4,5,6,7 */
				  SELECT @TRACK_ID = [col] FROM   #ITEM	WHERE  id = 2
					SET @TRACK_ID	= CAST(CAST(@TRACK_ID AS INT) AS VARCHAR)
					SELECT @BCR_NO = [col] FROM   #ITEM	WHERE  id = 3
					SELECT @InductionNO = [col] FROM   #ITEM	WHERE  id = 4
					SELECT @Loops = [col] FROM   #ITEM	WHERE  id = 5
		    	SELECT @Barcode1 = [col] FROM   #ITEM	WHERE  id = 7		
					/*条码处理 */
						set @Barcode1=substring(@Barcode1,2,len(@Barcode1)-2)	
						
					/*	SELECT TOP 1 @Barcode2=COL FROM   dbo.f_splitSTR(@Barcode1, '|') A	WHERE A.COL LIKE 'B%'	 */
					/*	IF ISNULL(@Barcode2,'')='' SET @Barcode2='NOREAD' */
					/*  SET @Barcode1=@Barcode2		 												 		 									 						 */
						
									 	 			 												     	  		    
			  	SET @i = @i + 1
			END
			set @p_msg= isnull(@p_msg,'')+ '[bcr_REQUEST]TRACK_ID='+isnull(@TRACK_ID,'')+',BCR_NO='+isnull(@BCR_NO,'')+',InductionNO='+isnull(@InductionNO,'')
									+',Loops='	+cast(@Loops as varchar)+',Barcode1='+isnull(@Barcode1,'')	 																	 																								 																																		   
		  SET @s_body='{"guid" : "'+cast(replace(newid(),'-','') as varchar(100))+'","containerNo" : "'+@Barcode1+'",
        "curAddress":"当前位置",
        "reqType":"请求类型",
        "reqTime":"请求时间",
        "temp1":"备用字段1",
        "temp2":"备用字段2",
        "temp3":"备用字段3"}'
		  set @s_header='Content-Type@@application/json'
			set @v_msg= @s_header+'#####'+@s_body 
			set @p_Send= @p_Send+'~~'+'HC2&='+@v_msg   
	
			/*把条码、小车号插入任务表，供post后组装plc的目的地回复报文用 
			1、先删掉该小车以前的记录
			2、插入该小车的最新记录*/	
	  	DELETE FROM wcs_tools_parcel	WHERE ParcelID=@TRACK_ID	AND	type='sd'											 																										          
  		INSERT INTO wcs_tools_parcel(barcode,type,status,ParcelID,msg) VALUES (@Barcode1,'sd','0',@TRACK_ID,@v_msg)	
    end
    SET @v_Temp_Pack  = SUBSTRING(@v_Temp_Pack, LEN(@v_Temp_Pack_Msg) + 2 + 1, LEN(@v_Temp_Pack))
  END

  if substring(@p_send,1,2)='~~'
    set @p_send=substring(@p_send,3,len(@p_send))
	 /*向不同的plc发送，特殊情况用到
    set @p_send='SD1&=393939'; */
  if isnull(@p_msg,'')<>''
  begin    
		SET @v_s    = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100
		set @p_msg = isnull(@p_msg,'')+',work_sec:'+cast(@v_s as varchar(10))
    EXEC [dbo].[sp_create_wcs_log]
	  	'bcr_rev',                      /*1、作业名称 */
	  	@Barcode1,                      /*2、容器号 */
	  	null,                           /*3、应去口 */
	  	NULL,                           /*4、实际口 */
		  NULL,                           /*5、读码器 */
		  NULL,                           /*6、分拣状态 */
		  @P_CODE,                        /*7、执行代码 */
	  	@p_msg,                         /*8、执行信息 */
		  'sp_sd_bcr_msg_rev',            /*9、执行过程 */
		  @v_s,                           /*10、执行时间 */
	  	@P_dvc_no,                      /*11、dvc编号 */  
	  	NULL,                           /*12、备用1 */
	  	NULL,                           /*13、备用2 */
	  	NULL,                           /*14、备用3 */
		  NULL,                           /*15、任务状态 */  
		  NULL,		                        /*16、上车状态 */
			null                            /*16、任务号 */                         
  end                   
END

