CREATE PROCEDURE [sp_sd_bcr_msg_send]   
  @P_dvc_no VARCHAR(20), @p_send VARCHAR(4000) OUT, 
   @P_CODE VARCHAR(100) OUT,
   @p_CMD_NAME VARCHAR(2000) out
AS
DECLARE @v_hand_cmd_id VARCHAR(100);
DECLARE @V_CMD_NAME VARCHAR(4000);
DECLARE @V_CMD VARCHAR(4000);
declare @V_LMSG_TIME VARCHAR(100);
DECLARE
  @V_heartbeat VARCHAR(4000),
  @v_DATE1     DATETIME = GETDATE(),
  @v_s         INT = 0,
  @NAME        VARCHAR(4000);

BEGIN
  SELECT   TOP 1
           @v_hand_cmd_id = a.hand_cmd_id, @V_CMD_NAME    = A.CMD_NAME, @V_CMD         = A.CMD
  FROM     HAND_CMD A
  WHERE    A.DVC_NO = @P_dvc_no
  ORDER BY a.Hand_Cmd_Id

  IF @@ROWCOUNT = 1
    BEGIN
      SET @p_send     = @V_CMD
      SET @p_CMD_NAME = @V_CMD_NAME

      /*执行完了就删除*/
      DELETE FROM HAND_CMD
      WHERE       HAND_CMD_ID = @V_HAND_CMD_ID

      /*SET @p_send=dbo.VarCharToHex(@p_send); */

      SET @v_s        = DATEDIFF(ms, @V_DATE1, GETDATE()) / 100

      SET @NAME       = 'PLC' + @P_dvc_no + '手动命令'
      EXEC [dbo].[sp_create_wcs_log]
	  	'@V_CMD_NAME',                   /*1、作业名称 */
	  	NULL,                           /*2、容器号 */
	  	null,                           /*3、应去口 */
	  	NULL,                           /*4、实际口 */
		  NULL,                           /*5、读码器 */
		  NULL,                           /*6、分拣状态 */
		  @P_CODE,                        /*7、执行代码 */
	  	@V_CMD,                         /*8、执行信息 */
		  'SP_PLC_SEND_MSG',              /*9、执行过程 */
		  @v_s,                           /*10、执行时间 */
	  	@P_dvc_no,                      /*11、dvc编号 */  
	  	NULL,                           /*12、备用1 */
	  	NULL,                           /*13、备用2 */
	  	NULL,                           /*14、备用3 */
		  NULL,                           /*15、任务状态 */  
		  NULL,		                        /*16、上车状态*/
			null                            /*16、任务号 */
    END
    
    /*向不同的plc发送，特殊情况用到
   if @P_dvc_no='plc1'
      set @p_send='plc2=333333'; */
      
   /*set @p_send='333333'; */
  /* set @p_CMD_NAME='test '+@p_send */
END

