CREATE PROCEDURE [sp_tools_guide]
	@P_TO_POS VARCHAR(100),
	@P_BCR VARCHAR(50),
	@P_Destination VARCHAR(50) OUT
AS
	DECLARE @plc_to_pos VARCHAR(20) 
	DECLARE @v_err_EXCEPTION_NO VARCHAR(50)
	BEGIN
		SET @P_Destination = ''
		/*输送线转移口处理 */
		SELECT top 1 @plc_to_pos = plc_to_pos
		FROM   WCS_GUIDE_config
		WHERE  wcs_to_pos LIKE '%' + @P_TO_POS + '%'
					 AND GUIDE = @P_BCR
		
		IF @@rowcount = 1
		    SET @P_Destination = @plc_to_pos
		ELSE
		    SET @P_Destination = dbo.f_tools_WcsToPlc(@P_TO_POS)
					
		IF ISNULL(@P_Destination, '') = ''   /*如果格口为空则赋值异常口并转换为PLC格口 */
		BEGIN 
		/*  SET @P_Destination = @P_TO_POS */
			 set @v_err_EXCEPTION_NO= dbo.f_tools_mem('bcr_err_0'+@P_BCR)
			 SET @P_Destination = dbo.f_tools_WcsToPlc(@v_err_EXCEPTION_NO)
		 END 
		 
	END



