-- ----------------------------
-- Procedure structure for sp_tools_plan
-- ----------------------------
DROP PROCEDURE [sp_tools_plan]
GO

CREATE PROCEDURE [sp_tools_plan](   
    @logical_address  VARCHAR(10),	/*区域 */
	  @mode  varchar(10),/*模式*/
    @POS   VARCHAR(50) OUT
)
AS
	DECLARE @ID INT 
	BEGIN
		/*分拣策略，按数量分配,可配置出口数量 */
		SELECT @ID = MIN(id)
		FROM   wcs_plan_config
		WHERE  logical_address = @logical_address
		       /*AND TEMP1=@mode */
		       AND qty > qty_deal
					 AND  status = '1'
					-- AND WCS_TO_POS IN(SELECT WCS_TO_POS FROM wcs_pos_config WHERE stn_st='1')/*出货模式的站台均分 */
		
		IF @ID IS NULL
		BEGIN
		    SELECT @ID = MIN(id)
		    FROM   wcs_plan_config
		    WHERE  logical_address = @logical_address 
			    /*AND TEMP1=@mode */
			    AND qty<>0
					AND  status = '1'
				--AND WCS_TO_POS IN(SELECT WCS_TO_POS FROM wcs_pos_config WHERE stn_st='1')/*出货模式的站台均分 */
		    
				IF ISNULL(@ID,'')<>''
		      UPDATE wcs_plan_config
		      SET    qty_deal = 0
		      WHERE  logical_address = @logical_address 
		END     	
		
		UPDATE wcs_plan_config
		SET    qty_deal = qty_deal + 1
		WHERE  ID = @ID 
		
		SELECT @POS = WCS_TO_POS
		FROM   wcs_plan_config
		WHERE  ID = @id
	END



GO

