-- Procedure structure for sp_wcs_clear_data
-- ----------------------------
DROP PROCEDURE [sp_wcs_clear_data]
GO
CREATE PROCEDURE [sp_wcs_clear_data]  
  @P_CODE VARCHAR(20) OUT,
  @P_MSG VARCHAR(400) OUT  
AS
  DECLARE @name varchar(50)
  DECLARE @datetime char(14)
  DECLARE @path varchar(255)
  DECLARE @bakfile varchar(255)
	DECLARE	@return_value int
	DECLARE @v_CODE VARCHAR(20)
	DECLARE @v_MSG VARCHAR(400)
BEGIN
  set @name='shopee_brazil'
  set @datetime=CONVERT(char(8),getdate(),112) + REPLACE(CONVERT(char(8),getdate(),108),':','')
  set @path='D:\shopee_brazil' 
 /* set @path='/usr/local/wcs/databak' */
  set @bakfile=@path+'\'+'Bak_'+@datetime+'_'+ @name+'.bak'
  backup database @name to disk=@bakfile with name=@name

  /*set @name='albs_wcss7'
  set @datetime=CONVERT(char(8),getdate(),112) + REPLACE(CONVERT(char(8),getdate(),108),':','')
  set @path='D:\WCS\data'
  set @bakfile=@path+'\'+'Bak_'+@datetime+'_'+ @name+'.bak'
  backup database @name to disk=@bakfile with name=@name*/

  /* Truncate the log by changing the database recovery model to SIMPLE. */
  ALTER DATABASE shopee_brazil
  SET RECOVERY SIMPLE;
  /* Shrink the truncated log file to 1 MB. */
  DBCC SHRINKFILE (shopee_brazil_Log, 1);
  /* Reset the database recovery model. */
  ALTER DATABASE shopee_brazil
  SET RECOVERY FULL;

DECLARE @BatchSize INT = 3000; /* 每次处理的行数 */
DECLARE @RowsAffected INT;

/* ========================================================= */
/* 第一阶段：wcs_task 数据搬移 (从原表删除并插入备份表) */
/* ========================================================= */
SET @RowsAffected = 1;
WHILE @RowsAffected > 0
BEGIN
    DELETE TOP (@BatchSize)
    FROM wcs_task
    OUTPUT 
        deleted.task_no, deleted.task_type, deleted.status, deleted.barcode, 
        deleted.length, deleted.width, deleted.height, deleted.volume, 
        deleted.weight, deleted.cur_pos, deleted.to_pos, deleted.create_date, 
        deleted.update_date, deleted.priority, deleted.temp1, deleted.temp2, 
        deleted.temp3, deleted.temp4, deleted.temp5, deleted.receiver_name, 
        deleted.shipment_id, deleted.url, deleted.parcelId
    INTO wcs_task_bak (
        task_no, task_type, status, barcode, length, width, height, volume, 
        weight, cur_pos, to_pos, create_date, update_date, priority, temp1, 
        temp2, temp3, temp4, temp5, receiver_name, shipment_id, 
        url, parcelId
    )
    WHERE create_date < CAST(GETDATE() AS DATE);

    SET @RowsAffected = @@ROWCOUNT;
    WAITFOR DELAY '00:00:00.500'; 
END

/* ========================================================= */
/* 第二阶段：wcs_log 数据搬移 (从原表删除并插入备份表) */
/* ========================================================= */
SET @RowsAffected = 1;
WHILE @RowsAffected > 0
BEGIN
    DELETE TOP (@BatchSize)
    FROM wcs_log
    OUTPUT 
        deleted.work_name, deleted.create_date, deleted.work_msg, deleted.barcode, 
        deleted.wms_pos, deleted.to_pos, deleted.cur_pos, deleted.bcr_no, 
        deleted.sort_status, deleted.parcel_id, deleted.unit_nr, deleted.work_code, 
        deleted.work_proc, deleted.proc_code, deleted.proc_msg, deleted.work_sec, 
        deleted.post_use_time, deleted.post_code, deleted.post_result, 
        deleted.post_result_all, deleted.rev_plc_msg, deleted.send_plc_msg, 
        deleted.comment, deleted.weight, deleted.length, deleted.wide, 
        deleted.high, deleted.loops, deleted.line_id, deleted.post_count, 
        deleted.dvc_no, deleted.update_date, deleted.temp1, deleted.temp2, 
        deleted.temp3, deleted.temp4, deleted.temp5, deleted.wcsTaskNum, 
        deleted.status, deleted.Induction_status
    INTO wcs_log_bak (
        work_name, create_date, work_msg, barcode, wms_pos, to_pos, cur_pos, 
        bcr_no, sort_status, parcel_id, unit_nr, work_code, work_proc, proc_code, 
        proc_msg, work_sec, post_use_time, post_code, post_result, post_result_all, 
        rev_plc_msg, send_plc_msg, comment, weight, length, wide, high, loops, 
        line_id, post_count, dvc_no, update_date, temp1, temp2, temp3, temp4, 
        temp5, wcsTaskNum, status, Induction_status
    )
    WHERE create_date < CAST(GETDATE() AS DATE);

    SET @RowsAffected = @@ROWCOUNT;
    WAITFOR DELAY '00:00:00.500'; 
END

/* ========================================================= */
/* 第三阶段：清理 wcs_task_bak 表中超过 8 天的历史数据 */
/* ========================================================= */
SET @RowsAffected = 1;
WHILE @RowsAffected > 0
BEGIN
    DELETE TOP (@BatchSize) 
    FROM wcs_task_bak 
    WHERE create_date < DATEADD(day, -8, CAST(GETDATE() AS DATE));

    SET @RowsAffected = @@ROWCOUNT;
    WAITFOR DELAY '00:00:00.500';
END

/* ========================================================= */
/* 第四阶段：清理 wcs_log_bak 表中超过 8 天的历史数据 */
/* ========================================================= */
SET @RowsAffected = 1;
WHILE @RowsAffected > 0
BEGIN
    DELETE TOP (@BatchSize) 
    FROM wcs_log_bak 
    WHERE create_date < DATEADD(day, -8, CAST(GETDATE() AS DATE));

    SET @RowsAffected = @@ROWCOUNT;
    WAITFOR DELAY '00:00:00.500';
END
  

DELETE FROM wcs_tools_feedback_bak 
        WHERE create_date < DATEADD(day, -14, CAST(GETDATE() AS DATE));
  
   /*delete from wcs_tools_label where DATEDIFF(day,create_date,getdate())*24 >= 24*4; */
   
   /*delete from wcs_tools_label_detail where DATEDIFF(day,create_date,getdate())*24 >= 24*4; */

	/*BEGIN TRY */
	/*	EXEC [shopee_brazil_SCADA_DB].[dbo].[sp_scada_clear_data]  */
	/*END TRY */
 /* BEGIN CATCH */
   /* SELECT @P_CODE = ERROR_NUMBER(), @P_MSG  = 'scada备份失败：' + ERROR_MESSAGE() */
 /* END CATCH */

END
