CREATE PROCEDURE [sp_wms_pack_nr](@pack_nr varchar(20) OUT)
AS
BEGIN
	UPDATE WCS_MEM_config
	SET    MEM_ITEM_VALUE = (
	           CASE 
	                WHEN MEM_ITEM_VALUE = '60000' THEN '1'
	                ELSE MEM_ITEM_VALUE + 1
	           END
	       ),
	       MEM_ITEM_OLDVALUE = MEM_ITEM_VALUE
	WHERE  MEM_ITEM_NO = 'pack_nr_wms'
	
	SELECT @pack_nr = MEM_ITEM_VALUE
	FROM   WCS_MEM_config
	WHERE  MEM_ITEM_NO = 'pack_nr_wms'
	
	set @pack_nr=replace(replace(convert(varchar(13),getdate(),120),'-',''),' ','')
	            +dbo.f_tools_lpad(cast(@pack_nr as varchar),5,'0')
END



