CREATE FUNCTION [f_plc_TimeStamp]
(
)
RETURNS VARCHAR(50)
AS





BEGIN
	DECLARE @TIMESTAMP     VARCHAR(50)
	DECLARE @CURRENT_TIME  VARCHAR(50)
	SET @CURRENT_TIME = CONVERT(VARCHAR(100), GETDATE(), 21)
	SET @TIMESTAMP = RIGHT(
	        dbo.f_tools_inttohex(CAST(SUBSTRING(@CURRENT_TIME, 3, 2) AS INT)),
	        2
	    ) +
	    
	    
	    RIGHT(
	        dbo.f_tools_inttohex(CAST(SUBSTRING(@CURRENT_TIME, 6, 2) AS INT)),
	        2
	    ) +
	    RIGHT(
	        dbo.f_tools_inttohex(CAST(SUBSTRING(@CURRENT_TIME, 9, 2)AS INT)),
	        2
	    ) +
	    RIGHT(
	        dbo.f_tools_inttohex(CAST(SUBSTRING(@CURRENT_TIME, 12, 2)AS INT)),
	        2
	    ) +
	    RIGHT(
	        dbo.f_tools_inttohex(CAST(SUBSTRING(@CURRENT_TIME, 15, 2)AS INT)),
	        2
	    ) +
	    RIGHT(
	        dbo.f_tools_inttohex(CAST(SUBSTRING(@CURRENT_TIME, 18, 2)AS INT)),
	        2
	    ) +
	    RIGHT(
	        dbo.f_tools_inttohex(CAST(SUBSTRING(@CURRENT_TIME, 21, 2)AS INT)),
	        2
	    ) +
	    RIGHT(
	        dbo.f_tools_inttohex(CAST(SUBSTRING(@CURRENT_TIME, 23, 1)AS INT)),
	        2
	    )
	
	RETURN @TIMESTAMP
END



