-- ----------------------------
-- Function structure for f_str_to_unicode
-- ----------------------------
DROP FUNCTION [f_str_to_unicode]
GO

CREATE function [f_str_to_unicode](@url varchar(max)) returns varchar(max)
as
begin
  declare @count int,@i int,@urlReturn varchar(max),@s varchar(50);
  set @count = len('a'+ isnull(@url,'')+'a')-2
  
  set @i=1
  set @urlReturn=''
  while (@i<= @count)
  begin
    set @s= substring(@url,@i,1)
    if UniCode(@s)>128
    begin
      set @s = '\u'+ format(UniCode(@s),'X')      
    end
    set @urlReturn= @urlReturn + @s
    set @i= @i+1
  end
  set @urlReturn = '"'+@urlReturn+'"'++char(10)
  return @urlReturn


end



GO

-- ----------------------------
-- Function structure for f_tools_BIN2_TO_HEXSTR
-- ----------------------------
DROP FUNCTION [f_tools_BIN2_TO_HEXSTR]
GO

CREATE FUNCTION [f_tools_BIN2_TO_HEXSTR](@BIN varbinary(8000))  
returns varchar(8000)
as
BEGIN
  DECLARE @R_VAL VARCHAR(8000),
          @LEN INT,
          @TEMP_VAL VARCHAR(100)
  SET @R_VAL = ''
  SET @LEN = DATALENGTH(@BIN)
  WHILE @LEN>0
    BEGIN
      SET @TEMP_VAL = SUBSTRING('0123456789ABCDEF',SUBSTRING(@BIN,@LEN,1)/16+1,1) + SUBSTRING('0123456789ABCDEF',SUBSTRING(@BIN,@LEN,1)%16+1,1)
      /*IF @TEMP_VAL != '00' */
      /*  BEGIN */
      /*    SET @R_VAL = @TEMP_VAL + @R_VAL */
      /*  END */
	  SET @R_VAL = @TEMP_VAL + @R_VAL
      SET @LEN = @LEN-1
    END
  WHILE(DATALENGTH(ISNULL(@R_VAL,'')) > 0)
    BEGIN
	  IF(SUBSTRING(@R_VAL,1,1) = '0')
	    BEGIN
		  SET @R_VAL = SUBSTRING(@R_VAL,2,DATALENGTH(ISNULL(@R_VAL,'')))
		END
	  ELSE
	    BEGIN
		  BREAK
		END
	END
  return @R_VAL
END



GO

-- ----------------------------
-- Function structure for f_tools_binarytodec
-- ----------------------------
DROP FUNCTION [f_tools_binarytodec]
GO

CREATE FUNCTION [f_tools_binarytodec] (@binarychar VARCHAR(21))
RETURNS INT
AS
BEGIN
    /* 声明变量 */
    DECLARE @stringlength INT, @returnvalue INT, @index INT
    DECLARE @currentchar CHAR(1);

    /* 初始化变量 */
    SET @index = 0;
    SET @returnvalue = 0;
    SET @stringlength = LEN(@binarychar);

    /* 循环遍历二进制字符串的每一位 */
    WHILE @index < @stringlength
    BEGIN
        SET @index = @index + 1;

        /* 获取当前位置的字符 */
        SET @currentchar = SUBSTRING(@binarychar, @index, 1);

        /* 只有当字符为'0'或'1'时才进行计算 */
        IF (@currentchar = '1' OR @currentchar = '0')
        BEGIN
            /* 将当前位值加到返回值上，使用 POWER 函数将二进制位转换为十进制值 */
            SET @returnvalue = @returnvalue + (CAST(@currentchar AS INT) * POWER(2, @stringlength - @index));
        END
    END

    /* 返回最终的十进制值 */
    RETURN @returnvalue;
END;



GO

-- ----------------------------
-- Function structure for f_tools_conv
-- ----------------------------
DROP FUNCTION [f_tools_conv]
GO

CREATE FUNCTION [f_tools_conv](@STR varchar(1000),@FRM_BASE int,@TO_BASE int)
returns varchar(100) as
BEGIN

  declare @RETURN_STR VARCHAR(100),
          @NUM1 VARBINARY(8)
  IF @FRM_BASE = 16 AND @TO_BASE = 10
    BEGIN
      SET @RETURN_STR = CONVERT(int,CONVERT(varbinary,cast('0x' + @STR as CHAR),1))
    END
  ELSE IF @FRM_BASE = 10 AND @TO_BASE = 16
    BEGIN
      SET @RETURN_STR = dbo.f_tools_BIN2_TO_HEXSTR(cast(CAST(@STR AS INT) as varbinary(255)))
    END
  return @RETURN_STR

END



GO

-- ----------------------------
-- Function structure for f_tools_HEX
-- ----------------------------
DROP FUNCTION [f_tools_HEX]
GO

CREATE FUNCTION [f_tools_HEX](@INPUT_STR Varchar(8000))  /*传入值为字符串 */
returns varchar(8000)
as
begin
  declare @SUB_CHAR varchar(10),  /*子字符的 */
          @SUB_CHAR_HEX varchar(10),
          @ModS int,
          @RETURN_STR varchar(8000),
          @LEN int,
          @Cres varchar(4),
          @TEMP_STR varchar(8000)
  set @RETURN_STR=''
  set @TEMP_STR = @INPUT_STR
  set @LEN=len(@TEMP_STR)
  set @RETURN_STR = ''
  while @LEN > 0
  begin
     set @SUB_CHAR = substring(@TEMP_STR,1,1)
     set @Cres=''
     set @SUB_CHAR_HEX = ''
     set @Mods = ascii(@SUB_CHAR) % 16
     set @Cres=Case when (@Mods > 9) then Char(Ascii('A') + @Mods - 10) 
                    else Cast(@Mods as varchar(4))
                    end
     
     set @SUB_CHAR_HEX = cast(Case when (ascii(@SUB_CHAR)/16 > 9) then Char(Ascii('A') + ascii(@SUB_CHAR)/16 - 10) 
                                   else Cast(ascii(@SUB_CHAR)/16 as varchar(4))
                                   end as varchar(10)) + @Cres
     set @RETURN_STR = @RETURN_STR + @SUB_CHAR_HEX
     if(@LEN > 1)
     begin
       set @TEMP_STR = substring(@TEMP_STR,2,@LEN - 1)
       set @LEN = @LEN - 1
     end
     else
     begin
       set @TEMP_STR = Convert(varbinary,'')
       set @LEN = 0
     end
  end
  return @RETURN_STR
end



GO

-- ----------------------------
-- Function structure for f_tools_Hex_To_Char
-- ----------------------------
DROP FUNCTION [f_tools_Hex_To_Char]
GO

CREATE FUNCTION [f_tools_Hex_To_Char]
(
	@p_SIN VARCHAR(MAX)
)
RETURNS VARCHAR(MAX)
AS


BEGIN
	DECLARE @v_stmp  VARCHAR(MAX)=''
	/*16进制转换为字符，比如输入4142，输出AB*/
	DECLARE @i       INT
	DECLARE @x       INT
	
	SET @i = 1   
	WHILE @i <= LEN(@p_SIN)
	BEGIN
	    SET @x = dbo.f_tools_HexToInt(SUBSTRING(@p_SIN, @i, 2))
	    SET @v_stmp = @v_stmp + CHAR(@x)
	    SET @i = @i + 2
	END 
	RETURN @v_stmp
END



