-- ----------------------------
-- Function structure for f_tools_lpad
-- ----------------------------
DROP FUNCTION [f_tools_lpad]
GO

CREATE FUNCTION [f_tools_lpad](@STR Nvarchar(4000),@LEN int,@PADCHAR char(1)) 
returns Nvarchar(4000) as
BEGIN

  declare @RETURN_STR Nvarchar(4000)
  SET @RETURN_STR = ''
  IF(@LEN <= 8000)
    BEGIN
      IF(LEN(@STR) <= @LEN) 
        BEGIN
          select @RETURN_STR = isnull(replicate(@PADCHAR,@LEN - len(isnull(@STR ,0))), '') + @STR
        END
      ELSE
        BEGIN
          SET @RETURN_STR = SUBSTRING(@STR,1,@LEN)
        END
    END

  return @RETURN_STR

END



