-- ----------------------------
-- Function structure for f_tools_splitSTR
-- ----------------------------
DROP FUNCTION [f_tools_splitSTR]
GO

CREATE FUNCTION [f_tools_splitSTR]
(
	@s      VARCHAR(8000),	/*待分拆的字符串 */
	@split  VARCHAR(10) /*数据分隔符 */
)
RETURNS @re TABLE(id INT IDENTITY(1, 1) PRIMARY KEY, col VARCHAR(4000))
AS

BEGIN
	DECLARE @splitlen INT
	SET @splitlen = LEN(@split + 'a') -2
	WHILE CHARINDEX(@split, @s) > 0
	BEGIN
	    INSERT @re
	    VALUES
	      (
	        LEFT(@s, CHARINDEX(@split, @s) -1)
	      )
	    SET @s = STUFF(@s, 1, CHARINDEX(@split, @s) + @splitlen, '')
	END
	INSERT @re
	VALUES
	  (
	    @s
	  )
	RETURN
END




GO

